mapper.select:
SELECT COUNT(*)
FROM project p JOIN team_member m ON m.team_id = p.team_id
WHERE m.user_id = #{userId}

SELECT p.id, p.team_id, p.name
FROM project p JOIN team_member m ON m.team_id = p.team_id
WHERE m.user_id = #{userId}
ORDER BY p.id LIMIT #{pageSize} OFFSET #{offset}

SELECT COUNT(*) FROM task
WHERE project_id = #{projectId}
AND status = #{status}

SELECT id, project_id, title, due_at, assignee, status, version
FROM task
WHERE project_id = #{projectId}
AND status = #{status}
ORDER BY id LIMIT #{pageSize} OFFSET #{offset}

SELECT COUNT(*)
FROM project p JOIN team_member m ON m.team_id = p.team_id
WHERE p.id = #{projectId} AND m.user_id = #{userId}

SELECT m.id, m.user_id, u.display_name, m.role
FROM team_member m JOIN teamflow_user u ON u.id = m.user_id
WHERE m.team_id = #{teamId} ORDER BY m.id LIMIT #{pageSize} OFFSET #{offset}

SELECT m.id, m.user_id, u.display_name, m.role
FROM team_member m JOIN teamflow_user u ON u.id = m.user_id
WHERE m.team_id = #{teamId} AND m.id = #{memberId}

SELECT m.id, m.user_id, u.display_name, m.role
FROM team_member m JOIN teamflow_user u ON u.id = m.user_id
WHERE m.team_id = #{teamId} AND m.user_id = #{userId}

mapper.update:
UPDATE task SET status = 'DONE', version = version + 1
WHERE id = #{taskId} AND project_id = #{projectId}
  AND status = 'IN_PROGRESS' AND version = #{version}
